"Analysis.CoeffOfVariation":{Name:"CV Proxy (Range / Mean × 100)",Hash:"CoeffOfVariation",DataType:"PreciseNumber",PictForm:{Section:"CalorieAnalysis",Group:"CalorieStats",Row:3,Width:3,InputType:"PreciseNumberReadOnly",DecimalPrecision:2}},"Analysis.LogCalorieSpread":{Name:"Log Spread (√(Range × Mean))",Hash:"LogCalorieSpread",DataType:"PreciseNumber",PictForm:{Section:"CalorieAnalysis",Group:"CalorieStats",Row:3,Width:3,InputType:"PreciseNumberReadOnly",DecimalPrecision:3}},"Analysis.AnalysisWeight":{Name:"Weight Factor",Hash:"AnalysisWeight",DataType:"Number",Default:"1",PictForm:{Section:"CalorieAnalysis",Group:"CalorieStats",Row:3,Width:3}},"Analysis.WeightedEnergy":{Name:"Weighted Energy (Index × Weight)",Hash:"WeightedEnergy",DataType:"PreciseNumber",PictForm:{Section:"CalorieAnalysis",Group:"CalorieStats",Row:3,Width:3,InputType:"PreciseNumberReadOnly",DecimalPrecision:3}},// ── Global state cross-reference (AppData-prefixed getvalue) ──
